import React, { useState } from 'react';
import { useGenerationTask } from '../hooks/use-generation-task.js';
import { useProjectModel } from '../../../model.js';
import { generateFunctionLibrary } from './generate.js';
import { ChooseNameStep } from './steps.js';
import {
  CompleteGeneration,
  CompleteGenerationMessage,
} from '../CompleteGeneration.js';

export const useGenerateFunctionLibrary = () => {
  const {
    model: { projectFolder, config },
  } = useProjectModel();
  const [name, setName] = useState<string>();

  const generationTask = useGenerationTask(async () => {
    if (name) {
      return generateFunctionLibrary(
        projectFolder,
        name,
        name,
        config.projectType === 'App' ? config.codeIdentifier : undefined
      );
    }
  }, [projectFolder, name]);

  return [
    <ChooseNameStep onSubmit={setName} name={name} />,
    <CompleteGeneration
      generationTask={generationTask}
      extensionType={'function library'}
      successMessage={CompleteGenerationMessage.SuccessMessage({
        learnMoreUrl: 'TBD',
      })}
      route={name}
    />,
  ];
};
