import { useMemo } from 'react';
import type { VariantOf } from 'variant';
import type { SelectGroup, SelectOption } from '@wix/cli-ui-kit';
import { match, variant } from 'variant';
import { useProjectModel } from '../../model.js';
import type { DocsExtensionType } from './docsExtensionType.js';
import { extensionSupportsProjectType } from './extensionHandlers.js';

const DevCenterGenerateFlow = variant({
  DashboardPage: {},
  DashboardPlugin: {},
  DashboardMenuPlugin: {},
  DashboardModal: {},
  DashboardExternalPage: {},
  Event: {},
  DataCollection: {},
  ServicePlugin: {},
  EmbeddedScript: {},
  SitePlugin: {},
  CustomElement: {},
  EditorReactComponent: {},
  AppTools: {},
  FunctionLibrary: {},
  HttpEndpoint: {},
});

export type GenerateFlow = VariantOf<typeof DevCenterGenerateFlow>;

type GenerateFlowKey = keyof typeof DevCenterGenerateFlow;

// Every picker flow is backed by an extension handler, which owns the metadata
// describing where the extension can be generated. Keyed by the docs extension
// type, so a new type without a picker flow fails to compile.
const FLOW_KEY_BY_DOCS_EXTENSION_TYPE: Record<
  DocsExtensionType,
  GenerateFlowKey
> = {
  DASHBOARD_PAGE: 'DashboardPage',
  DASHBOARD_MODAL: 'DashboardModal',
  DASHBOARD_PLUGIN: 'DashboardPlugin',
  DASHBOARD_MENU_PLUGIN: 'DashboardMenuPlugin',
  DASHBOARD_EXTERNAL_PAGE: 'DashboardExternalPage',
  EMBEDDED_SCRIPT: 'EmbeddedScript',
  CUSTOM_ELEMENT: 'CustomElement',
  EDITOR_REACT_COMPONENT: 'EditorReactComponent',
  SITE_PLUGIN: 'SitePlugin',
  EVENT: 'Event',
  SERVICE_PLUGIN: 'ServicePlugin',
  DATA_COLLECTION: 'DataCollection',
  APP_TOOLS: 'AppTools',
  FUNCTION_LIBRARY: 'FunctionLibrary',
  HTTP_ENDPOINT: 'HttpEndpoint',
};

const getGenerateFlowByKey = (
  key: GenerateFlowKey
): SelectOption<GenerateFlow> => {
  return match(key, {
    DashboardPage: () => ({
      key,
      title: 'Dashboard Page',
      value: DevCenterGenerateFlow.DashboardPage(),
    }),
    DashboardModal: () => ({
      key,
      title: 'Dashboard Modal',
      value: DevCenterGenerateFlow.DashboardModal(),
    }),
    DashboardPlugin: () => ({
      key,
      title: 'Dashboard Plugin',
      value: DevCenterGenerateFlow.DashboardPlugin(),
    }),
    DashboardMenuPlugin: () => ({
      key,
      title: 'Dashboard Menu Plugin',
      value: DevCenterGenerateFlow.DashboardMenuPlugin(),
    }),
    DashboardExternalPage: () => ({
      key,
      title: 'Dashboard External Page',
      value: DevCenterGenerateFlow.DashboardExternalPage(),
    }),
    EmbeddedScript: () => ({
      key,
      title: 'Embedded Script',
      value: DevCenterGenerateFlow.EmbeddedScript(),
    }),
    SitePlugin: () => ({
      key,
      title: 'Site Plugin',
      value: DevCenterGenerateFlow.SitePlugin(),
    }),
    Event: () => ({
      key,
      title: 'Backend Event',
      value: DevCenterGenerateFlow.Event(),
    }),
    ServicePlugin: () => ({
      key,
      title: 'Service Plugin',
      value: DevCenterGenerateFlow.ServicePlugin(),
    }),
    DataCollection: () => ({
      key,
      title: 'Data Collection',
      value: DevCenterGenerateFlow.DataCollection(),
    }),
    CustomElement: () => ({
      key,
      title: 'Custom Element',
      value: DevCenterGenerateFlow.CustomElement(),
    }),
    EditorReactComponent: () => ({
      key,
      title: 'Editor React Component',
      value: DevCenterGenerateFlow.EditorReactComponent(),
    }),
    AppTools: () => ({
      key,
      title: 'App Tools',
      value: DevCenterGenerateFlow.AppTools(),
    }),
    FunctionLibrary: () => ({
      key,
      title: 'Function Library',
      value: DevCenterGenerateFlow.FunctionLibrary(),
    }),
    HttpEndpoint: () => ({
      key,
      title: 'HTTP Endpoint',
      value: DevCenterGenerateFlow.HttpEndpoint(),
    }),
  });
};

export const getGenerateFlowByDocsExtensionType = (type: DocsExtensionType) =>
  getGenerateFlowByKey(FLOW_KEY_BY_DOCS_EXTENSION_TYPE[type]);

const EXPERIMENTAL_EXTENSION_TYPES: ReadonlySet<DocsExtensionType> = new Set([
  'FUNCTION_LIBRARY',
]);

const FLOW_GROUPS: ReadonlyArray<{
  title: string;
  extensionTypes: readonly DocsExtensionType[];
}> = [
  {
    title: 'Dashboard',
    extensionTypes: [
      'DASHBOARD_PAGE',
      'DASHBOARD_MODAL',
      'DASHBOARD_PLUGIN',
      'DASHBOARD_MENU_PLUGIN',
      'DASHBOARD_EXTERNAL_PAGE',
    ],
  },
  {
    title: 'Site',
    extensionTypes: [
      'EMBEDDED_SCRIPT',
      'SITE_PLUGIN',
      'CUSTOM_ELEMENT',
      'EDITOR_REACT_COMPONENT',
      'FUNCTION_LIBRARY',
    ],
  },
  {
    title: 'Backend',
    extensionTypes: [
      'HTTP_ENDPOINT',
      'EVENT',
      'SERVICE_PLUGIN',
      'DATA_COLLECTION',
      'APP_TOOLS',
    ],
  },
];

export const useGenerateFlows = ({
  experimental,
}: {
  experimental: boolean;
}): Array<SelectGroup<GenerateFlow>> => {
  const {
    model: { config },
  } = useProjectModel();
  const { projectType } = config;

  return useMemo(() => {
    return FLOW_GROUPS.flatMap(({ title, extensionTypes }) => {
      const items = extensionTypes
        .filter(
          (type) => experimental || !EXPERIMENTAL_EXTENSION_TYPES.has(type)
        )
        .filter((type) => extensionSupportsProjectType(type, projectType))
        .map(getGenerateFlowByDocsExtensionType);

      return items.length > 0 ? [{ title, items }] : [];
    });
  }, [experimental, projectType]);
};
