import React, { useState } from 'react';
import { useGenerationTask } from '../hooks/use-generation-task.js';
import { useProjectModel } from '../../../model.js';
import { generateHttpEndpoint } from './generate.js';
import { ChooseNameStep } from './steps.js';
import {
  CompleteGeneration,
  CompleteGenerationMessage,
} from '../CompleteGeneration.js';

export const useGenerateHttpEndpoint = () => {
  const {
    model: { projectFolder },
  } = useProjectModel();
  const [name, setName] = useState<string>();

  const generationTask = useGenerationTask(async () => {
    if (name) {
      return generateHttpEndpoint(projectFolder, name);
    }
  }, [projectFolder, name]);

  return [
    <ChooseNameStep onSubmit={setName} name={name} />,
    <CompleteGeneration
      generationTask={generationTask}
      extensionType={'HTTP endpoint'}
      successMessage={CompleteGenerationMessage.SuccessMessage({
        learnMoreUrl:
          'https://dev.wix.com/docs/build-apps/develop-your-app/develop-an-app-with-the-cli/supported-extensions/backend/http-endpoints/about-http-endpoints',
      })}
      route={name}
    />,
  ];
};
