import { existsSync } from 'node:fs';
import { join } from 'node:path';
import { useCallback } from 'react';
import { resolveHttpEndpointsTarget } from '../../../components/GenerateCommand/http-endpoint/resolve.js';
import { VALID_RELATIVE_PATH_REGEX } from './common.js';

export const useHttpEndpointNameValidation = (projectFolder: string) => {
  return useCallback(
    async (name: string): Promise<true | string> => {
      if (!VALID_RELATIVE_PATH_REGEX.test(name)) {
        return 'Name must be lowercase letters, numbers and hyphens, optionally in slash-separated segments';
      }

      const { endpointsDir } = await resolveHttpEndpointsTarget(projectFolder);

      if (existsSync(join(endpointsDir, `${name}.ts`))) {
        return 'An HTTP endpoint with this name already exists.';
      }

      return true;
    },
    [projectFolder]
  );
};
