import { useCallback } from 'react';
import { getFunctionLibraryExtensionsDir } from '@wix/cli-astro-definitions';
import {
  composeValidations,
  pathAvailableValidation,
  pathValidation,
  useValidation,
} from './common.js';

function createFunctionLibraryNameValidation(projectFolder: string) {
  const extensionsDir = getFunctionLibraryExtensionsDir(projectFolder);
  return composeValidations([
    [
      pathValidation,
      "Name can't include special characters, spaces or uppercase letters",
    ],
    [
      pathAvailableValidation(extensionsDir),
      'A function library extension with this name already exists.',
    ],
  ]);
}

export const useFunctionLibraryNameValidation = (projectFolder: string) => {
  const validation = useValidation(
    createFunctionLibraryNameValidation(projectFolder)
  );

  return useCallback(validation, [validation, projectFolder]);
};
